START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030144437_AddAIWorkoutHistory') THEN
    CREATE TABLE "AIWorkoutHistories" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "UserId" integer NOT NULL,
        "MemberId" integer NOT NULL,
        "Goal" character varying(200) NOT NULL,
        "Level" character varying(20) NOT NULL,
        "DaysPerWeek" integer NOT NULL,
        "PlanJson" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_AIWorkoutHistories" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_AIWorkoutHistories_Members_MemberId" FOREIGN KEY ("MemberId") REFERENCES "Members" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_AIWorkoutHistories_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030144437_AddAIWorkoutHistory') THEN
    CREATE INDEX "IX_AIWorkoutHistories_MemberId" ON "AIWorkoutHistories" ("MemberId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261030144437_AddAIWorkoutHistory') THEN
    CREATE INDEX "IX_AIWorkoutHistories_UserId_Id" ON "AIWorkoutHistories" ("UserId", "Id");
    END IF;
END $EF$;

DO $EF$
BEGIN
